function valid(x,z,y=player.y,walking=true){if(!world||!inWorld(x,z)||(walking&&y<3&&vehicles?.blocks(x,z)))return false;const b=world.bounds;const floor=districts?.surface(x,z)||0;if(walking&&floor>y-1.85+jumpY+.65)return false;return x>b.minX&&x<b.maxX&&z>b.minZ&&z<b.maxZ&&!world.obstacles.some(o=>!o.disabled&&(o.maxY===undefined||y-1.85+jumpY<o.maxY-.05)&&(o.minY===undefined||y>o.minY)&&Math.abs(x-o.x)<o.w&&Math.abs(z-o.z)<o.d);}
