const map=$('map').getContext('2d');function drawMap(){map.clearRect(0,0,190,190);map.fillStyle='#a0ced31a';for(const o of world.obstacles){const x=95+(o.x-player.x)*1.15,z=95+(o.z-player.z)*1.15;map.fillRect(x-o.w*1.15,z-o.d*1.15,o.w*2.3,o.d*2.3);}const dot=(p,c,r)=>{const x=95+(p.x-player.x)*1.15,z=95+(p.z-player.z)*1.15;if(x<4||x>186||z<4||z>186)return;map.fillStyle=c;map.beginPath();map.arc(x,z,r,0,7);map.fill();};world.relays.forEach(r=>dot(r.g.position,r.done?'#8ba19e':'#ffda74',4));world.drones.filter(d=>d.hp>0).forEach(d=>dot(d.g.position,d.stun?'#6ce4f0':'#ff6f63',3));dot(world.exit,'#8ce7e5',4);cast?.actors.filter(a=>a.g.visible).forEach(a=>dot(a.g.position,'#a8ddae',3));const quest=questTarget();if(quest)dot(quest.position,'#aaffdb',5);map.save();map.translate(95,95);map.rotate(-yaw);map.fillStyle='#d8fffb';map.beginPath();map.moveTo(0,-7);map.lineTo(-4,5);map.lineTo(4,5);map.fill();map.restore();}
