 let dx=Number(keys.has('KeyD'))-Number(keys.has('KeyA'))+touchMove.x,dz=Number(keys.has('KeyS'))-Number(keys.has('KeyW'))+touchMove.z;const len=Math.max(1,Math.hypot(dx,dz));dx/=len;dz/=len;const speed=(keys.has('ShiftLeft')||touchSprint)?(campaign.upgrades.includes('mobility')?10:8):4.5,vx=(dx*Math.cos(yaw)+dz*Math.sin(yaw))*speed*dt,vz=(-dx*Math.sin(yaw)+dz*Math.cos(yaw))*speed*dt;
 // Substeps preserve collisions without slowing traversal on lower frame rates.
 const steps=Math.max(1,Math.ceil(Math.hypot(vx,vz)/.2));for(let i=0;i<steps;i++){if(valid(player.x+vx/steps,player.z))player.x+=vx/steps;if(valid(player.x,player.z+vz/steps))player.z+=vz/steps;const ground=districts.surface(player.x,player.z)+1.85;if(ground>player.y)player.y=ground;}
 const targetY=districts.surface(player.x,player.z)+1.85;if(player.y>targetY){fallSpeed+=dt*12;player.y=Math.max(targetY,player.y-fallSpeed*dt);}else fallSpeed=0;
 const onRoof=player.y>6;if(onRoof&&!wasOnRoof){campaign.rooftopVisits++;save();say('The roof route is clear. There is an archive recording up here.');}wasOnRoof=onRoof;
 if(Math.abs(dx)+Math.abs(dz)>.2&&elapsed-lastFootstep>.48){lastFootstep=elapsed;spatialTone(player,90,.05,.025);if(speed>=8&&!campaign.upgrades.includes('stealth')){lastNoise=elapsed;noisePosition.copy(player);}}
