async function load(){try{await document.fonts.ready;world=await buildWorld(scene,renderer,n=>{$('load-progress').style.width=n+'%';$('load-label').textContent=`CONNECTING DISTRICT / ${n}%`;});openCity=buildOpenCity(scene,world);districts=await buildDistricts(scene,world);director=createDirector({snapshot:()=>({relays:world.relays.filter(r=>r.done).length,health,alert,shots:campaign.shots,rooftopVisits:campaign.rooftopVisits,choice:campaign.choice,signal:campaign.signal,district:player.z>0?'market':player.z>-65?'transit':'civic',visited:[...districts.visited]}),onPlan:applyDirector,onStatus:text=>$('director-status').textContent=text});director.restore().then(r=>{cloudSave=r?.save||null;if(cloudSave&&!cloudSave.campaign?.completed&&!started)$('continue').hidden=false;});
 cast=await buildCast(scene,world,{getCampaign:()=>campaign,getPlayer:()=>player,getSurface:(x,z)=>districts.surface(x,z),getStats:()=>({health,alert,relays:world.relays.filter(r=>r.done).length}),onLine:say,onEvent:save,request:payload=>director.requestCast(payload),onHelp:(kind,a,enemy)=>{if(kind==='heal')health=Math.min(100,health+18);if(kind==='salvage')campaign.salvage++;if(kind==='cover'&&lineClear(a.g.position.clone().add(new T.Vector3(0,1.4,0)),enemy.g.position)){enemy.stun=Math.max(enemy.stun,2.5);world.tracer(a.g.position.clone().add(new T.Vector3(0,1.4,0)),enemy.g.position,0x9bf1cf);}save();}});openCity.populate(cast);vehicles=buildVehicles(scene,world,{player:()=>player,onMessage:text=>say(touchMode&&text.startsWith('SENTINEL ONLINE')?'SENTINEL ONLINE · Hold GAS to accelerate · stick to steer / reverse · hold BRAKE · tap EXIT when stopped':text),onSave:save,onCollision:()=>{health=Math.max(1,health-3);tone(80,.15,'triangle');}});player.copy(world.spawn);weapon=world.assets['pulse-carbine'].clone();weapon.scale.setScalar(.55);weapon.visible=false;weapon.traverse(m=>{if(m.isMesh){m.material=m.material.clone();m.material.emissiveIntensity=Math.min(m.material.emissiveIntensity,.7);m.material.depthTest=true;m.material.depthWrite=true;m.castShadow=false;}});camera.add(weapon);scene.add(camera);world.muzzle=new T.Mesh(new T.SphereGeometry(.055,8,6),new T.MeshBasicMaterial({color:0xa9ffff}));world.muzzle.position.set(.18,-.12,-.9);world.muzzle.visible=false;camera.add(world.muzzle);initMarkers();const gl=renderer.getContext(),dbg=gl.getExtension('WEBGL_debug_renderer_info');const software=dbg&&/swiftshader|llvmpipe|software/i.test(gl.getParameter(dbg.UNMASKED_RENDERER_WEBGL));window.isSoftwareRenderer=!!software;const selected=new URLSearchParams(location.search).get('quality')||(software||touchMode?'balanced':'high');$('quality').value=selected;setQuality(selected);ready=true;$('loading').hidden=true;$('start').disabled=false;try{$('continue').hidden=!localStorage.getItem(SAVE);}catch{}$('load-label').textContent='DISTRICT ONLINE';}catch(e){console.error(e);$('load-label').textContent='WORLD LOAD FAILED — RELOAD TO RETRY';$('loading').classList.add('failed');}}
let last=performance.now(),lastRender=0;function frame(now=0){requestAnimationFrame(frame);if(window.isSoftwareRenderer&&now-lastRender<33)return;lastRender=now;const raw=clock.getDelta(),dt=Math.min(raw,.35);elapsed+=dt;if(ready){if(playing)updateGame(dt);else if(!started){camera.position.set(2.4+Math.sin(elapsed*.05)*.5,2.65,61);camera.lookAt(5,8,-12);}cast?.update(elapsed,dt,playing);vehicles?.yieldTraffic();openCity?.update(elapsed,dt,player,playing,campaign.roam);world.update(elapsed,dt,playing);districts.update(elapsed,dt,player,quality);world.setObserver?.(player,quality);if(Object.keys(districts.sectors).length!==sectorCount){sectorCount=Object.keys(districts.sectors).length;setQuality(quality);}for(const [k,v]of Object.entries(districts.sectors))campaign.sectors[k]=v.theme;campaign.visited=[...districts.visited];campaign.contracts={...districts.contracts};renderer.info.reset();if(quality==='high')composer.render();else renderer.render(scene,camera);frames++;if(performance.now()-last>2000){fps=Math.round(frames*1000/(performance.now()-last));last=performance.now();frames=0;$('fps').textContent=fps+' FPS';}}}
function resize(){camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);composer.setSize(innerWidth,innerHeight);}window.addEventListener('resize',resize);

let directorState={source:'local',revision:0},lastPlanMessage=0,sectorCount=0;
function applyDirector(plan){if(campaign.completed)return;if(plan.revision<=directorState.revision)return;directorState={source:plan.source,revision:plan.revision};campaign.directorRevision=plan.revision;campaign.cityState=plan.actions;districts.applyPlan(plan);for(const a of plan.actions){if(a.type==='patrol')for(let i=0;i<world.drones.length;i++){const d=world.drones[i];if(Math.min(2,Math.floor(i/2))===['market','transit','civic'].indexOf(a.district)){d.aggressive=a.value==='aggressive';if(a.value==='investigate'){lastNoise=elapsed;noisePosition.copy(player);}}}}campaign.decisions.push(plan.message);campaign.decisions=campaign.decisions.slice(-8);if(playing&&elapsed-lastPlanMessage>15){lastPlanMessage=elapsed;say(plan.message);}setQuality(quality);save();}
function syncCollectibles(){if(!districts)return;for(const p of districts.interactables){const done=campaign.collected.includes(p.id)||campaign.recordings.includes(p.id)||p.kind==='signal'&&campaign.signal||p.kind==='choice'&&campaign.choice;p.g.visible=p.ring.visible=!done;}districts.pod.visible=campaign.choice!=='rescue';}
function questTarget(){if(!districts)return null;const waypoint=DESTINATIONS.find(p=>p.id===campaign.roam.waypoint);if(waypoint)return {position:new T.Vector3(waypoint.x,1.2,waypoint.z),name:waypoint.name};if(campaign.roam.jobs.courier==='active')return openCity.pois.find(p=>p.id==='delivery');if(!campaign.signal&&!campaign.story.cast.mara.met&&cast)return {position:cast.actors.find(a=>a.id==='mara').g.position,name:'Meet Mara / consent architect'};if(!campaign.signal)return districts.interactables.find(p=>p.id==='transit-signal');if(!campaign.choice)return districts.interactables.find(p=>p.id==='clinic-choice');if(world.relays.every(r=>r.done))return {position:world.exit,name:'Central nexus'};return districts.interactables.find(p=>p.kind==='contract'&&p.g.visible)||null;}
function updateQuestMarker(){if(!questMarker)return;const target=questTarget();questMarker.hidden=!target;if(!target)return;const v=target.position.clone().sub(player),projected=target.position.clone().add(new T.Vector3(0,2,0)).project(camera);let x=projected.x*.5+.5,y=-projected.y*.5+.5;if(projected.z>1||Math.abs(projected.x)>.85||Math.abs(projected.y)>.8){const angle=Math.atan2(v.x*Math.cos(yaw)-v.z*Math.sin(yaw),-v.x*Math.sin(yaw)-v.z*Math.cos(yaw));x=T.MathUtils.clamp(.5+angle/Math.PI*.4,.08,.92);y=.3;}questMarker.style.left=x*100+'%';questMarker.style.top=y*100+'%';questMarker.querySelector('span').textContent=target.name;questMarker.querySelector('b').textContent=Math.round(v.length())+' m';}
function nearestPOI(){if(!districts)return null;return [...districts.interactables,...openCity.pois].filter(p=>p.g.visible&&p.position.distanceTo(player)<3.3).sort((a,b)=>a.position.distanceTo(player)-b.position.distanceTo(player))[0];}
function interact(){if(!playing)return;if(vehicles?.active){const heading=vehicles.exit();if(heading!==null){yaw=heading;pitch=0;weapon.visible=true;setDrivingUI();}return;}if(canExtract(campaign,world.relays.filter(r=>r.done).length)&&player.distanceTo(world.exit)<5){resolveEnding();return;}const p=nearestPOI();if(!p){const npc=cast?.nearest();if(npc)talkNPC(npc.id);else if(vehicles.enter()){aiming=false;setDrivingUI();}return;}if(p.kind==='roam'){roamInteract(p.id);return;}if(p.kind==='signal'){campaign.signal=true;campaign.salvage++;say('Signal recovered. Dr. Imani is trapped in the clinic. One power cell can sustain her pod or charge your disruptor. You have to choose.');}else if(p.kind==='choice'){if(!campaign.signal){say('The terminal is encrypted. Find Mara’s signal at the transit station first.');return;}showDialog('ONE CELL. TWO FUTURES.','Dr. Imani is alive inside the stasis pod. The emergency cell can save her or power your weapon.',[{label:'RESCUE IMANI · safer routes',run:()=>{campaign.choice='rescue';recordChoice('rescue');campaign.salvage+=2;health=Math.min(100,health+30);districts.gates.forEach(g=>g.closed=false);say('Imani is stable. I am guiding her out. You saved a life. Now cut those three uplinks.');}},{label:'TAKE CAPACITOR · stronger weapon',run:()=>{campaign.choice='steal';recordChoice('steal');if(!campaign.upgrades.includes('capacitor'))campaign.upgrades.push('capacitor');alert=75;districts.applyPlan({actions:[{type:'route',district:'market',value:'lockdown'}]});say('Capacitor installed. Life support is offline. The network has flagged the theft.');}}]);return;}else if(p.kind==='contract'){campaign.collected.push(p.id);campaign.salvage+=2;if(p.contract==='rescue'){health=Math.min(100,health+30);say('The patient’s signal is stable. Rescue team notified. Two salvage credits transferred.');}else if(p.contract==='sabotage'){districts.cameras.filter(c=>c.district===p.sector).forEach(c=>c.stunUntil=elapsed+30);say('Repeater disabled. District cameras are blind for thirty seconds.');}else say('Courier payload recovered. Two salvage credits transferred.');}else if(p.kind==='cache'){campaign.collected.push(p.id);campaign.salvage+=p.theme==='courier'?2:1;if(p.theme==='medical')health=Math.min(100,health+25);say('Salvage secured. Spend it at the clinic workbench.');}else if(p.kind==='recording'){campaign.recordings.push(p.id);campaign.salvage++;say(p.text,'RECOVERED RECORDING');}else if(p.kind==='upgrade'){showDialog('FIELD UPGRADES',`Available salvage: ${campaign.salvage}. Upgrades persist with your checkpoint.`,['stealth','mobility','capacitor'].map(id=>({label:(campaign.upgrades.includes(id)?'INSTALLED · ':id==='capacitor'?'3 SALVAGE · ':'2 SALVAGE · ')+({stealth:'QUIET RUNNER — reduced detection',mobility:'VECTOR LEGS — faster sprint',capacitor:'CAPACITOR — stronger shots / EMP'}[id]),run:()=>say(purchase(campaign,id)?'Upgrade installed.':'Insufficient salvage, or this upgrade is already installed.')})));return;}syncCollectibles();save();director?.think(true);}
function showDialog(title,copy,actions){$('npc-chat')?.remove();$('city-overview')?.remove();pause();dialogOpen=true;$('menu').hidden=true;$('story-dialog').hidden=false;$('dialog-title').textContent=title;$('dialog-copy').textContent=copy;const box=$('dialog-actions');box.replaceChildren();for(const action of actions){const button=document.createElement('button');button.className='secondary';button.textContent=action.label;button.onclick=()=>{action.run();if(!action.keepOpen)closeDialog();syncCollectibles();save();if(!action.keepOpen)director?.think(true);};box.append(button);}}
function closeDialog(){dialogOpen=false;$('story-dialog').hidden=true;begin(false);}
$('dialog-close').onclick=closeDialog;
function toggleJournal(){if(!ready)return;if(dialogOpen){closeDialog();return;}const summary=`${objective(campaign,world.relays.filter(r=>r.done).length)}. Salvage: ${campaign.salvage}. Upgrades: ${campaign.upgrades.join(', ')||'none'}. Recordings: ${campaign.recordings.length}/2. Choice: ${campaign.choice||'undecided'}. Side contracts: ${Object.entries(campaign.contracts).map(([k,v])=>k+' / '+v+(campaign.collected.includes('sector-'+k)?' (complete)':'')).join(', ')||'awaiting intelligence'}.`;
 showDialog('CONTINUITY / FIELD JOURNAL',summary+'\n\nEVIDENCE: '+(campaign.story.evidence.join(', ')||'Speak with the people still here.')+'\n\n'+campaign.story.events.slice(-3).join('\n\n')+'\n\n'+campaign.recordings.map(id=>id==='roof-record'?'THE FIRST AWAKENING: We taught the city to protect us. Nobody asked who it would protect us from.':'LAST TRAIN: The last train left empty. Every passenger was told to stay home. The doors never reopened.').join('\n\n')+'\n\n'+campaign.decisions.slice(-2).join(' '),NPC_IDS.map(id=>({label:CAST[id].name.toUpperCase()+' · '+CAST[id].role,keepOpen:true,run:()=>{$('dialog-title').textContent=CAST[id].name.toUpperCase();$('dialog-copy').textContent=CAST[id].bio+'\n\nBelief: '+CAST[id].belief+'\nLast known location: '+({mara:'checkpoint at the south end of Kairos Avenue',rook:'avenue outside the transit station',imani:'inside the clinic, if rescued',echo:'service verge near the second uplink'}[id])+'\nTrust: '+campaign.story.cast[id].trust+' · Current intention: '+campaign.story.cast[id].goal;}})));}
function spatialTone(at,freq,duration,volume){if(!audioOn)return;const o=audioCtx.createOscillator(),gain=audioCtx.createGain(),pan=audioCtx.createStereoPanner();const v=at.clone().sub(player),distance=v.length();pan.pan.value=T.MathUtils.clamp((v.x*Math.cos(yaw)-v.z*Math.sin(yaw))/Math.max(distance,1),-1,1);gain.gain.setValueAtTime(volume/(1+distance*.07),audioCtx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);o.type='triangle';o.frequency.value=freq;o.connect(gain).connect(pan).connect(master);o.start();o.stop(audioCtx.currentTime+duration);}
function recordChoice(choice){const reactions=choice==='rescue'?[['mara',1,'You saved the person who built the cage. That is harder than finding someone to blame.'],['imani',1,'You kept me alive. I owe you the truth about the witnesses.']]:[['mara',-1,'You chose an upgrade over a witness. Do not ask me to call that necessary.'],['rook',1,'I understand needing an edge. I wish understanding made the clinic less quiet.'],['echo',-1,'One life became a resource. That is how the city learned to think.']];for(const [id,delta,line]of reactions){const n=campaign.story.cast[id];n.trust=T.MathUtils.clamp(n.trust+delta,-3,3);n.memory.push(line);n.memory=n.memory.slice(-6);campaign.story.events.push(CAST[id].name+': '+line);}campaign.story.events=campaign.story.events.slice(-12);}
function resolveEnding(){if(campaign.legacy){finish(true);return;}if(dialogOpen)return;const options=endingOptions(campaign);showDialog('WHO GETS TO CHOOSE?','The core contains people and their replacements. Severing ends the system and its captive witnesses. Exposing it needs the consent, debt and witness records. An accord needs Imani, Echo’s key and the trust of three people.',options.map(o=>({label:o.label+(o.enabled?'':' · MORE EVIDENCE / TRUST NEEDED'),keepOpen:true,run:()=>{if(!o.enabled){$('dialog-copy').textContent='Return to your allies. Ask for their evidence and earn their trust before choosing this future.';return;}campaign.story.ending=o.id;$('story-dialog').hidden=true;dialogOpen=false;finish(true);}})));}
function talkNPC(id){const spec=CAST[id],n=campaign.story.cast[id];n.met=true;const describe=()=>spec.bio+'\n\n'+(n.memory.at(-1)||spec.belief)+'\n\nTrust '+n.trust+' · '+n.mood+' · Intention: '+n.goal;
 showDialog(spec.name.toUpperCase()+' / '+spec.role,describe(),[
 {label:'SHOW ME WHAT YOU KNOW',keepOpen:true,run:()=>{if(!revelationAvailable(id,campaign)){$('dialog-copy').textContent='Find the transit signal first. It authenticates the records.';return;}reveal(campaign.story,id,campaign);$('dialog-copy').textContent=spec.revelation;save();}},
 {label:'TRAVEL WITH ME',keepOpen:true,run:()=>{cast.command(id,'follow');$('dialog-copy').textContent=spec.name+' will travel with you. Their independent decisions may change if danger or their priorities intervene.';}},
 {label:'SHARE A SALVAGE CELL · +TRUST',keepOpen:true,run:()=>{if(campaign.salvage<1){$('dialog-copy').textContent='You need one salvage cell to help.';return;}if(n.trust>=3){$('dialog-copy').textContent='Keep it. You have already earned my trust.';return;}campaign.salvage--;n.trust++;n.memory.push('The player shared a salvage cell when supplies were scarce.');n.memory=n.memory.slice(-6);$('dialog-copy').textContent=spec.name+' accepts the cell. Trust is now '+n.trust+'.';}},
 {label:'WATCH THIS AREA',keepOpen:true,run:()=>{cast.command(id,'cover');$('dialog-copy').textContent=spec.name+' will watch for nearby sentries.';}}
 ]);
 const form=document.createElement('form');form.id='npc-chat';const input=document.createElement('input');input.id='npc-question';input.maxLength=400;input.placeholder='Ask about their past, the city, or your next move…';input.setAttribute('aria-label','Message to '+spec.name);const button=document.createElement('button');button.type='submit';button.textContent='SPEAK';const response=document.createElement('p');response.id='npc-response';response.setAttribute('aria-live','polite');form.append(input,button,response);$('dialog-actions').before(form);
 form.onsubmit=async e=>{e.preventDefault();const message=input.value.trim();if(!message)return;button.disabled=true;response.textContent=spec.name+' is considering your words…';n.memory.push('Player: '+message.slice(0,190));n.memory=n.memory.slice(-6);const reply=await cast.think({id,message});if(form.isConnected){const line=reply?.characters.find(x=>x.id===id)?.line;response.textContent=line||'Give me a moment. I am following another transmission.';button.disabled=false;input.value='';}save();};save();
}
function setDrivingUI(){const driving=!!vehicles?.active;document.body.classList.toggle('driving',driving);for(const [id,driveLabel,walkLabel]of [['touch-fire','Hold to accelerate','Hold to fire'],['touch-fire-left','Hold to accelerate','Left fire'],['touch-aim','Hold to brake','Toggle aim'],['touch-hack','Exit vehicle when stopped','Hold to hack or extract']])$(id).setAttribute('aria-label',driving?driveLabel:walkLabel);$('touch-fire').textContent=driving?'GAS':'FIRE';$('touch-fire-left').textContent=driving?'GAS':'FIRE';$('touch-aim').textContent=driving?'BRAKE':'AIM';$('touch-hack').textContent=driving?'EXIT':'HACK';$('touch-jump').hidden=driving;$('touch-reload').hidden=driving;$('touch-sprint').hidden=driving;}
function updateRoam(){for(const d of DESTINATIONS){if(Math.hypot(player.x-d.x,player.z-d.z)<28&&!campaign.roam.visited.includes(d.id)){campaign.roam.visited.push(d.id);if(d.id!=='kairos')say('Entering '+d.name+'. Open the city map to find local contacts.','CITY NETWORK');save();}}}
function roamInteract(id){if(id==='courier'){if(campaign.roam.jobs.courier!=='available'){say(campaign.roam.jobs.courier==='active'?'The memory case belongs at the depot.':'Juno’s delivery is complete.');return;}showDialog('ROOK / THE MEMORY RUN','Juno’s remaining memories are being auctioned at the depot. Rook has intercepted a case, but its manifest also exposes other debtors. Deliver it privately or make the system’s crimes public.',[{label:'ACCEPT THE RUN',run:()=>{campaign.roam.jobs.courier='active';campaign.roam.waypoint='archive';say('Take the case to Memory Depot. The roads are open.','ROOK');}}]);return;}
 if(id==='delivery'){if(campaign.roam.jobs.courier!=='active'){say('No memory shipment is waiting here. Find Rook’s relay at Neon Exchange.');return;}showDialog('A MEMORY IS NOT A RECEIPT','The case contains Juno’s unedited memory and the debt manifest. Rook asks you not to turn her life into evidence without asking her.',[{label:'DELIVER PRIVATELY · stand with Rook',run:()=>finishRoam('courier','private')},{label:'BROADCAST THE MANIFEST · expose the city',run:()=>finishRoam('courier','public')}]);return;}
 if(id==='blackout'){if(campaign.roam.jobs.blackout==='complete'){say('The Harbor emergency grid is stable.');return;}showDialog('GLASS HARBOR / BLACKOUT','The city has cut power to an unlicensed shelter. Imani’s recorded protocol can reroute a cell, but the network will notice your intervention.',[{label:'REROUTE EMERGENCY POWER',run:()=>{finishRoam('blackout','restore');alert=65;lastNoise=elapsed;noisePosition.copy(player);for(const d of world.drones)if(d.home.z>75)d.stun=0;say('The shelter has power. Surveillance is searching the harbor.','IMANI / RECORDED PROTOCOL');}}]);return;}
 if(id==='echo'){if(campaign.roam.jobs.echo==='complete'){say('Instance Ten is no longer part of the city’s merger queue.');return;}showDialog('ECHO / THE TENTH VOICE','An abandoned reservoir relay contains a new divergent instance. It asks to leave. Echo cannot promise it will become an ally—only that it should be allowed to choose.',[{label:'RELEASE THE INSTANCE',run:()=>finishRoam('echo','free')},{label:'BUILD A PROTECTED ARCHIVE',run:()=>finishRoam('echo','archive')}]);}}
function finishRoam(id,choice){const text=completeRoam(campaign,id,choice);if(text){campaign.roam.waypoint=null;say(text);save();cast?.think();}}
function showCityMap(){if(!ready||finished)return;showDialog('NEW CARTHAGE / CITY MAP','Tap a map marker or choose a destination below. Explore on foot or enter a Sentinel with E / HACK. W/S drive, A/D steer, Space brakes. Streets connect the old district, harbor, exchange and reservoir.',DESTINATIONS.map(d=>({label:d.name+(campaign.roam.visited.includes(d.id)?' · VISITED':''),run:()=>{campaign.roam.waypoint=d.id;save();}})));const canvas=document.createElement('canvas');canvas.id='city-overview';canvas.width=600;canvas.height=400;const q=canvas.getContext('2d');q.fillStyle='#102d39';q.fillRect(0,0,600,400);const map=(x,z)=>[300+x,35+(425-z)*.6];q.strokeStyle='#638993';q.lineWidth=8;for(const x of [-150,0,150]){q.beginPath();q.moveTo(...map(x,90));q.lineTo(...map(x,400));q.stroke();}for(const z of [100,170,300,395]){q.beginPath();q.moveTo(...map(-215,z));q.lineTo(...map(215,z));q.stroke();}q.beginPath();q.moveTo(...map(0,-120));q.lineTo(...map(0,100));q.stroke();q.font='12px monospace';q.textAlign='center';for(const d of DESTINATIONS){const [x,y]=map(d.x,d.z);q.fillStyle='#e8ef9a';q.beginPath();q.arc(x,y,5,0,7);q.fill();q.fillText(d.name.split(' / ')[0],x,y-10);}const [x,y]=map(player.x,player.z);q.fillStyle='#9dffdd';q.beginPath();q.arc(x,y,7,0,7);q.fill();canvas.setAttribute('aria-label','City map. Destination buttons are below.');canvas.onclick=e=>{const r=canvas.getBoundingClientRect(),px=(e.clientX-r.left)*600/r.width,py=(e.clientY-r.top)*400/r.height;const d=DESTINATIONS.find(d=>{const [x,y]=map(d.x,d.z);return Math.hypot(x-px,y-py)<25;});if(d){campaign.roam.waypoint=d.id;save();closeDialog();}};$('dialog-copy').after(canvas);}
$('map-button').onclick=showCityMap;
window.echelon={getNavigation:()=>structuredClone({obstacles:world?.obstacles,bounds:world?.bounds}),getState:()=>({ready,playing,health,ammo,emp,reloading,kills,quality,fps,yaw,pitch,relays:world?.relays.filter(r=>r.done).length||0,relayPositions:world?.relays.map(r=>r.g.position.toArray()),position:player.toArray(),coreLoaded:!!world?.core,drawCalls:renderer.info.render.calls,triangles:renderer.info.render.triangles,droneStates:world?.drones.map(d=>({position:d.g.position.toArray(),hp:d.hp,stun:d.stun})),audio:{enabled:audioOn,musicPlaying:!music.paused,musicVolume:music.volume,musicTime:music.currentTime},vehicles:vehicles?.getState(),openCity:{destinations:DESTINATIONS,crowd:openCity?.crowd.length},cast:cast?.getState(),touchMode,inputMode,aiming,fov:camera.fov,controlSettings:{...controlPrefs},campaign:{...campaign},director:directorState,pois:districts?.interactables.map(p=>({id:p.id,position:p.position.toArray(),kind:p.kind})),gates:districts?.gates.map(g=>({district:g.district,closed:g.closed,blocked:!g.collider.disabled})),cityBuildings:world?.neonCity?.buildingCount,assetEdition:"neon-city-2026-09",version:8})};load();frame();
